def min_cost_connect_cities(n, roads):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    total = 0
    merges = 0
    for a, b, cost in sorted(roads, key=lambda r: r[2]):
        if union(a, b):
            total += cost
            merges += 1
    return total if merges == n - 1 else -1
